1	import type * as Cloudflare from "@alchemy.run/cloudflare";
2	import { assert, describe, it } from "@effect/vitest";
3	import { hashToken } from "@surveybeat/domain";
4	import { RuntimeContext } from "alchemy/RuntimeContext";
5	import * as Effect from "effect/Effect";
6	import { HttpServerRequest } from "effect/http/HttpServerRequest";
7	import type * as HttpServerResponse from "effect/http/HttpServerResponse";
8	import { readdirSync, readFileSync } from "node:fs";
9	import { DatabaseSync } from "node:sqlite";
10	import type { Organizations } from "./EmailDelivery.ts";
11	import { submissionRoutes } from "./SubmissionRoutes.ts";
12	
13	const d1MigrationsDir = new URL("../d1-migrations/", import.meta.url);
14	
15	const EDIT_KEY = "CANARY-EDIT-KEY-raw-value";
16	const CANARY_ANSWER = "CANARY-ANSWER";
17	
18	const setupD1 = (): { readonly d1: DatabaseSync; readonly queryDb: Cloudflare.D1.QueryDatabaseClient } => {
19	  const d1 = new DatabaseSync(":memory:");
20	  for (const file of readdirSync(d1MigrationsDir)
21	    .filter((f) => f.endsWith(".sql"))
22	    .sort()) {
23	    d1.exec(readFileSync(new URL(file, d1MigrationsDir), "utf8"));
24	  }
25	
26	  const statement = (sql: string, binds: ReadonlyArray<unknown>) => ({
27	    bind: (...values: ReadonlyArray<unknown>) => statement(sql, values),
28	    first: <T>() =>
29	      Effect.sync(
30	        () => (d1.prepare(sql).get(...(binds as Array<null | string | number>)) ?? null) as T | null,
31	      ),
32	    all: <T>() =>
33	      Effect.sync(() => ({
34	        results: d1.prepare(sql).all(...(binds as Array<null | string | number>)) as Array<T>,
35	      })),
36	    run: () =>
37	      Effect.sync(() => {
38	        d1.prepare(sql).run(...(binds as Array<null | string | number>));
39	        return { results: [] };
40	      }),
41	  });
42	
43	  const queryDb = {
44	    prepare: (sql: string) => statement(sql, []),
45	  } as unknown as Cloudflare.D1.QueryDatabaseClient;
46	
47	  return { d1, queryDb };
48	};
49	
50	/**
51	 * Fake Organizations that answers every method with the same Submission answers and records each
52	 * call. Any call, including `getByName` itself, lands in `calls`.
53	 */
54	const recordingOrganizations = () => {
55	  const calls: Array<string> = [];
56	  const result = {
57	    _tag: "Success",
58	    answers: [{ questionVersionId: "qv-1", value: 5, comment: CANARY_ANSWER }],
59	    shownToLead: false,
60	  };
61	  const organizationFor = (): unknown =>
62	    new Proxy(
63	      {},
64	      {
65	        get: (_target, method) => {
66	          if (typeof method !== "string") return undefined;
67	          calls.push(method);
68	          return () => Effect.succeed(result);
69	        },
70	      },
71	    );
72	  const organizations = new Proxy(
73	    {},
74	    {
75	      get: (_target, method) => {
76	        if (typeof method !== "string") return undefined;
77	        calls.push(method);
78	        return () => organizationFor();
79	      },
80	    },
81	  ) as unknown as Organizations;
82	  return { organizations, calls };
83	};
84	
85	const makeRequest = (
86	  method: string,
87	  urlPath: string,
88	  body?: Record<string, unknown>,
89	  headers?: Record<string, string>,
90	): HttpServerRequest => {
91	  const bodyText = body ? JSON.stringify(body) : "";
92	  return {
93	    method,
94	    // HttpServerRequest.url is the path plus query, not an absolute URL.
95	    url: urlPath,
96	    headers: {
97	      "content-type": "application/json",
98	      ...(headers ?? {}),
99	    },
100	    text: Effect.succeed(bodyText),
101	    json: Effect.sync(() => (body ? body : {})),
102	  } as unknown as HttpServerRequest;
103	};
104	
105	const bodyText = (response: HttpServerResponse.HttpServerResponse): string => {
106	  const body = response.body;
107	  switch (body._tag) {
108	    case "Empty":
109	      return "";
110	    case "Uint8Array":
111	      return new TextDecoder().decode(body.body);
112	    case "Raw":
113	      return JSON.stringify(body.body);
114	    default:
115	      throw new Error(`unexpected response body ${body._tag}`);
116	  }
117	};
118	
119	const cases: ReadonlyArray<{
120	  readonly name: string;
121	  readonly build: (path: string, editKeyHash: string) => HttpServerRequest;
122	}> = [
123	  {
124	    name: "body editKeyHash",
125	    build: (path, hash) => makeRequest("POST", path, { editKeyHash: hash }),
126	  },
127	  {
128	    name: "body edit_key_hash",
129	    build: (path, hash) => makeRequest("POST", path, { edit_key_hash: hash }),
130	  },
131	  {
132	    name: "query editKeyHash",
133	    build: (path, hash) => makeRequest("POST", `${path}?editKeyHash=${hash}`),
134	  },
135	  {
136	    name: "query edit_key_hash",
137	    build: (path, hash) => makeRequest("POST", `${path}?edit_key_hash=${hash}`),
138	  },
139	  {
140	    name: "query editKey (raw Edit key)",
141	    build: (path) => makeRequest("POST", `${path}?editKey=${EDIT_KEY}`),
142	  },
143	  {
144	    name: "body editKey (raw Edit key)",
145	    build: (path) => makeRequest("POST", path, { editKey: EDIT_KEY }),
146	  },
147	  {
148	    name: "header x-edit-key (raw Edit key)",
149	    build: (path) => makeRequest("POST", path, undefined, { "x-edit-key": EDIT_KEY }),
150	  },
151	];
152	
153	const runRoute = (path: string, testCase: (typeof cases)[number]) =>
154	  Effect.gen(function* () {
155	    const { d1, queryDb } = setupD1();
156	    const editKeyHash = yield* Effect.promise(() => hashToken(EDIT_KEY));
157	    d1.prepare(
158	      "INSERT INTO submission_index (edit_key_hash, organization_id, round_id) VALUES (?, ?, ?)",
159	    ).run(editKeyHash, "org-1", "round-1");
160	    const { organizations, calls } = recordingOrganizations();
161	    const response = yield* submissionRoutes(organizations, queryDb).pipe(
162	      Effect.provideService(HttpServerRequest, testCase.build(path, editKeyHash)),
163	      // The Organization methods read the alchemy runtime; the fake needs only an empty one.
164	      Effect.provideService(RuntimeContext, {} as RuntimeContext["Service"]),
165	    );
166	    return { response, text: bodyText(response), calls };
167	  });
168	
169	describe("Submission Worker never returns answers for an Edit key (ADR 0005, issue #122)", () => {
170	  for (const testCase of cases) {
171	    it.effect(`POST /my-answers with ${testCase.name} is not found and reaches no Organization`, () =>
172	      Effect.gen(function* () {
173	        const { response, text, calls } = yield* runRoute("/my-answers", testCase);
174	        assert.strictEqual(response.status, 404);
175	        assert.notInclude(text, CANARY_ANSWER);
176	        assert.deepStrictEqual(calls, [], "no Organization method may be called");
177	      }),
178	    );
179	  }
180	
181	  // Every route the Worker serves, even when the Organization would hand answers back.
182	  for (const path of ["/exchange", "/first-answer", "/answer", "/submit", "/my-answers"]) {
183	    for (const testCase of cases) {
184	      it.effect(`POST ${path} with ${testCase.name} returns no answers`, () =>
185	        Effect.gen(function* () {
186	          const { text } = yield* runRoute(path, testCase);
187	          assert.notInclude(text, CANARY_ANSWER);
188	          assert.notInclude(text, "answers");
189	        }),
190	      );
191	    }
192	  }
193	});
